create table hub_internal.workbooks (
 id text primary key, course text not null, unit int not null, title text not null, vocabulary jsonb not null,
 unique(course,unit)
);
create table hub_internal.workbook_lessons (
 id text primary key, workbook_id text not null references hub_internal.workbooks, position int not null,
 title text not null, icon text not null, questions jsonb not null,
 published boolean not null default true, revision bigint not null default 0, unique(workbook_id,position)
);
create table hub_internal.workbook_classes (
 lesson_id text references hub_internal.workbook_lessons, class_id uuid references public.school_classes, primary key(lesson_id,class_id)
);
create table hub_internal.workbook_students (
 lesson_id text references hub_internal.workbook_lessons, student_id uuid references public.students, primary key(lesson_id,student_id)
);
create table hub_internal.workbook_attempts (
 id uuid primary key default gen_random_uuid(), lesson_id text not null references hub_internal.workbook_lessons,
 student_id uuid not null references public.students, questions jsonb not null, answers jsonb not null default '[]',
 score int not null default 0, completed_at timestamptz, created_at timestamptz not null default now()
);
create index on hub_internal.workbook_attempts(lesson_id,student_id);
create unique index on hub_internal.workbook_attempts(lesson_id,student_id) where completed_at is null;
alter table hub_internal.workbooks enable row level security;
alter table hub_internal.workbook_lessons enable row level security;
alter table hub_internal.workbook_classes enable row level security;
alter table hub_internal.workbook_students enable row level security;
alter table hub_internal.workbook_attempts enable row level security;
revoke all on hub_internal.workbooks,hub_internal.workbook_lessons,hub_internal.workbook_classes,hub_internal.workbook_students,hub_internal.workbook_attempts from public,anon,authenticated;

create function hub_internal.workbook_scope(p_student uuid,p_lesson text) returns boolean
language sql stable set search_path='' as $$
 select exists(select 1 from public.students s join public.school_classes c on c.id=s.class_id
 join hub_internal.workbook_lessons l on l.id=p_lesson join hub_internal.workbooks b on b.id=l.workbook_id
 where s.id=p_student and s.active and c.archived_at is null and c.grade_level='ثالث ثانوي' and c.course=b.course and
 (exists(select 1 from hub_internal.workbook_classes x where x.lesson_id=l.id and x.class_id=c.id)
  or exists(select 1 from hub_internal.workbook_students x where x.lesson_id=l.id and x.student_id=s.id)))
$$;

create function hub_internal.workbook_report(p_student uuid default null) returns jsonb
language sql stable set search_path='' as $$
 with attempts as (
   select a.lesson_id,a.student_id,count(*) attempts,count(*) filter(where a.completed_at is not null) completed,
     max(round(100.0*a.score/jsonb_array_length(a.questions))) filter(where a.completed_at is not null) best,
     jsonb_agg(round(100.0*a.score/jsonb_array_length(a.questions)) order by a.completed_at) filter(where a.completed_at is not null) scores
   from hub_internal.workbook_attempts a where p_student is null or a.student_id=p_student group by a.lesson_id,a.student_id
 ), eligible as (
   select l.id,l.title,l.position,b.id book,b.unit,s.full_name,c.name class_name,coalesce(a.attempts,0) attempts,
     coalesce(a.completed,0) completed,a.best,a.scores,l.published
   from hub_internal.workbook_lessons l join hub_internal.workbooks b on b.id=l.workbook_id cross join public.students s join public.school_classes c on c.id=s.class_id
   left join attempts a on a.lesson_id=l.id and a.student_id=s.id
   where (p_student is null or s.id=p_student) and
     (a.attempts>0 or (hub_internal.workbook_scope(s.id,l.id) and (p_student is null or l.published)))
 )
 select coalesce(jsonb_agg(to_jsonb(e) order by class_name,full_name,position),'[]') from eligible e
$$;

create function public.hub_workbook(p_op text,p_data jsonb default '{}',p_token text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare staff boolean:=hub_internal.learning_teacher() and p_token is null;
 sid uuid; bid text:=p_data->>'book'; lid text:=p_data->>'id';
 l hub_internal.workbook_lessons%rowtype; a hub_internal.workbook_attempts%rowtype;
 qs jsonb; q jsonb; choice text; step integer; right_answer boolean; complete boolean;
 classes jsonb; pupils jsonb;
begin
 if not staff then
   sid:=hub_internal.learning_student(p_token);
   if sid is null then raise insufficient_privilege;end if;
 end if;
 if p_op='catalog' then
   return (select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('lessons',
    (select jsonb_agg((to_jsonb(x)-'questions')||jsonb_build_object('completed',exists(select 1
       from hub_internal.workbook_attempts w where w.lesson_id=x.id and w.student_id=sid and w.completed_at is not null))
       order by x.position) from hub_internal.workbook_lessons x where x.workbook_id=b.id
       and (staff or (x.published and hub_internal.workbook_scope(sid,x.id)))))), '[]')
    from hub_internal.workbooks b where (bid is null or b.id=bid) and
      (staff or exists(select 1 from hub_internal.workbook_lessons x where x.workbook_id=b.id and x.published and hub_internal.workbook_scope(sid,x.id))));
 end if;
 if p_op='report' then return hub_internal.workbook_report(sid);end if;
 select * into l from hub_internal.workbook_lessons where id=lid for update;
 if not found then raise insufficient_privilege;end if;
 if staff then
   if p_op='edit' then
     return to_jsonb(l)||jsonb_build_object('classes',(select coalesce(jsonb_agg(class_id),'[]') from hub_internal.workbook_classes where lesson_id=lid),
       'students',(select coalesce(jsonb_agg(student_id),'[]') from hub_internal.workbook_students where lesson_id=lid));
   end if;
   if p_op<>'save' or l.revision is distinct from (p_data->>'revision')::bigint then raise exception 'تغيّر الدرس. أعيدي فتحه ثم حاولي مجددًا.';end if;
   qs:=p_data->'questions'; classes:=p_data->'classes'; pupils:=p_data->'students';
   if jsonb_typeof(qs) is distinct from 'array' or jsonb_array_length(qs) not between 1 and 100 then raise exception 'أضيفي من سؤال واحد إلى 100 سؤال';end if;
   for q in select value from jsonb_array_elements(qs) loop
     if coalesce(q->>'type','') not in ('match','image','correction','choice') or coalesce(length(trim(q->>'prompt')),0) not between 1 and 600
       or (q->>'type'='image' and coalesce(q->>'image','') not in ('car','shampoo','detergent','brand','sneakers'))
       or jsonb_typeof(q->'choices') is distinct from 'array' or jsonb_array_length(q->'choices') not between 2 and 15
       or jsonb_typeof(q->'correct') is distinct from 'string' or not(q->'choices' @> jsonb_build_array(q->'correct'))
       or exists(select 1 from jsonb_array_elements(q->'choices') x where jsonb_typeof(x)<>'string' or length(trim(x#>>'{}')) not between 1 and 500)
       or (select count(distinct x) from jsonb_array_elements(q->'choices') x)<>jsonb_array_length(q->'choices')
       then raise exception 'راجعي نص السؤال والخيارات والإجابة الصحيحة';end if;
   end loop;
   if jsonb_typeof(classes) is distinct from 'array' or jsonb_typeof(pupils) is distinct from 'array' then raise exception 'تخصيص غير صالح';end if;
   if coalesce((p_data->>'published')::boolean,false) and jsonb_array_length(classes)+jsonb_array_length(pupils)=0 then raise exception 'اختاري فصلًا أو طالبة قبل النشر';end if;
   if exists(select 1 from jsonb_array_elements_text(classes) x where not exists(select 1 from public.school_classes c join hub_internal.workbooks b on b.id=l.workbook_id where c.id::text=x and c.course=b.course and c.grade_level='ثالث ثانوي' and c.archived_at is null))
   or exists(select 1 from jsonb_array_elements_text(pupils) x where not exists(select 1 from public.students s join public.school_classes c on c.id=s.class_id join hub_internal.workbooks b on b.id=l.workbook_id where s.id::text=x and c.course=b.course and c.grade_level='ثالث ثانوي' and s.active and c.archived_at is null))
   then raise exception 'التخصيص لطالبات ثالث ثانوي في هذا المقرر فقط';end if;
   update hub_internal.workbook_lessons set questions=qs,published=coalesce((p_data->>'published')::boolean,false),revision=revision+1 where id=lid;
   delete from hub_internal.workbook_classes where lesson_id=lid;
   delete from hub_internal.workbook_students where lesson_id=lid;
   insert into hub_internal.workbook_classes select distinct lid,x::uuid from jsonb_array_elements_text(classes) x;
   insert into hub_internal.workbook_students select distinct lid,x::uuid from jsonb_array_elements_text(pupils) x;
   return '{}';
 end if;
 if not l.published or not hub_internal.workbook_scope(sid,lid) then raise insufficient_privilege;end if;
 if p_op='start' then
   select * into a from hub_internal.workbook_attempts where lesson_id=lid and student_id=sid
     order by (completed_at is null) desc,created_at desc,id desc limit 1;
   if a.id is null or (a.completed_at is not null and coalesce((p_data->>'retry')::boolean,false)) then
     insert into hub_internal.workbook_attempts(lesson_id,student_id,questions) values(lid,sid,l.questions) returning * into a;
   end if;
 elsif p_op='answer' then
   select * into a from hub_internal.workbook_attempts where id=(p_data->>'attempt')::uuid and lesson_id=lid and student_id=sid for update;
   if not found then raise insufficient_privilege;end if;
   step:=(p_data->>'step')::integer;
   if step is null or step<0 or step>=jsonb_array_length(a.questions) or step>jsonb_array_length(a.answers) then raise exception 'السؤال غير متاح';end if;
   q:=a.questions->step;choice:=p_data->>'choice';
   if choice is null or not(q->'choices' @> jsonb_build_array(choice)) then raise exception 'اختيار غير صالح';end if;
   if step=jsonb_array_length(a.answers) and a.completed_at is null then
     right_answer:=choice=q->>'correct';complete:=step+1=jsonb_array_length(a.questions);
     update hub_internal.workbook_attempts set answers=answers||jsonb_build_array(choice),score=score+case when right_answer then 1 else 0 end,
      completed_at=case when complete then now() end where id=a.id returning * into a;
   end if;
   right_answer:=(a.answers->>step)=(q->>'correct');
 else raise insufficient_privilege;
 end if;
 return jsonb_build_object('id',a.id,'score',a.score,'step',jsonb_array_length(a.answers),'total',jsonb_array_length(a.questions),
   'completed',a.completed_at is not null,'correct',right_answer,'expected',case when right_answer is false then q->>'correct' end,
   'question',(a.questions->jsonb_array_length(a.answers))-'correct');
end $$;

revoke all on function hub_internal.workbook_scope(uuid,text),hub_internal.workbook_report(uuid),public.hub_workbook(text,jsonb,text) from public,anon,authenticated;
grant execute on function public.hub_workbook(text,jsonb,text) to anon,authenticated;

create or replace function hub_internal.leadership_data() returns jsonb language sql stable set search_path='' as $$
 select hub_internal.leadership_base_data()||jsonb_build_object(
  'fluency',hub_internal.fluency_progress(null),
  'mirror',(select jsonb_agg(x-'suggestions' order by ord) from jsonb_array_elements(hub_internal.mirror_report()) with ordinality r(x,ord)),
  'workbook',hub_internal.workbook_report(null))
$$;

create or replace function public.hub_family(p_invite text,p_pin text,p_message text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare data jsonb; sid uuid;
begin
 data:=hub_internal.hub_family(p_invite,p_pin,p_message);
 if data is null then return null;end if;
 select student_id into strict sid from public.parent_access where invite_hash=extensions.digest(p_invite,'sha256');
 return data||jsonb_build_object('fluency',hub_internal.fluency_progress(sid),'workbook',hub_internal.workbook_report(sid));
end $$;
