('mg3-u5-grammar','mg3-u5',3,'Grammar','💡','[{"type":"choice","prompt":"You can put it ___ you like.","choices":["so that","in case","since","wherever"],"correct":"wherever"},{"type":"choice","prompt":"___ I was late, I took a taxi.","choices":["Unless","So that","Because","Wherever"],"correct":"Because"},{"type":"choice","prompt":"I won''t go to the party ___ she invites me.","choices":["as soon as","unless","so that","because of"],"correct":"unless"},{"type":"choice","prompt":"They will go to England ___ they can improve their speaking skills.","choices":["so that","because of","wherever","until"],"correct":"so that"},{"type":"choice","prompt":"Please take your cell phone ___ you need it.","choices":["because of","since","now that","in case"],"correct":"in case"},{"type":"choice","prompt":"He drove slowly ___ the rain.","choices":["if","even if","because of","in case"],"correct":"because of"},{"type":"correction","prompt":"Choose the correction: Because my son finishes his homework, he can’t go out.","choices":["Wherever my son finishes his homework, he can’t go out.","Because of my son finishes his homework, he can’t go out.","Unless my son finishes his homework, he can’t go out."],"correct":"Unless my son finishes his homework, he can’t go out."},{"type":"correction","prompt":"Choose the correction: I like Sara so that she is honest.","choices":["I like Sara wherever she is honest.","I like Sara because she is honest.","I like Sara because of she is honest."],"correct":"I like Sara because she is honest."},{"type":"correction","prompt":"Choose the correction: I will give you a map since you find the way.","choices":["I will give you a map so that you can find the way.","I will give you a map because of you find the way.","I will give you a map wherever you find the way."],"correct":"I will give you a map so that you can find the way."}]'::jsonb),
